contract.endpoint:
POST /api/work-orders/{workOrder}/task-template/reload
      body: { "task_template_id": int (required, exists task_templates where is_active) }
      200: { success: true, message, data: WorkOrderResource } (data.task_template = { id, name } del modello caricato)
      403: senza `work-orders.update` o fuori perimetro
      409: commessa chiusa; oppure task del modello gia' completati: { success: false, message, data: { completed_tasks_count: int } }
      422: task_template_id mancante, inesistente o disattivato
